<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/tests/support/FixtureDirectory.php';
test('F3 bounded mock performance evidence',function()use($db,$f): void{
    $percentile=static function(array $values,float $p): float{sort($values);return $values[max(0,(int)ceil(count($values)*$p)-1)];};
    $report=['php'=>PHP_VERSION,'os'=>PHP_OS_FAMILY,'database'=>'MariaDB isolated test','workload'=>'1000 services on discovery customer; 32 operations per mode/concurrency; 60 services on separate authenticated HTTP customer; 30 requests per view','results'=>[]];
    $fixture=serviceFixture($db,1000);$engine=new \Hostider\Services\Engine($db,$fixture['config']);do{$ids=$engine->discover($fixture['order']['id'],$fixture['actor'],\Hostider\Core\Id::uuid());}while(count($ids)<1000);same(1000,count($ids));
    (new \Hostider\Hosting\Pools($db,$fixture['config']))->configure($fixture['product'],10000);$operations=[];foreach($ids as $id){$operations[]=$engine->repository->find($id,lock:false)['current_operation_id'];}
    $offset=0;$directory=dirname(__DIR__).'/storage/service-test-'.bin2hex(random_bytes(8));mkdir($directory,0700,true);
    try{foreach([1,4,8] as $concurrency){foreach(['claim','work'] as $mode){$batch=array_slice($operations,$offset,32);$offset+=32;$children=[];$times=[];$before=$db->execute("SHOW GLOBAL STATUS WHERE Variable_name IN ('Innodb_row_lock_time','Innodb_deadlocks')")->fetchAll();$start=hrtime(true);
        for($i=0;$i<$concurrency;++$i){$file=$directory.'/'.$i.'.json';$assigned=[];foreach($batch as $index=>$operation){if($index%$concurrency===$i){$assigned[]=$operation;}}file_put_contents($file,json_encode(['key'=>$fixture['config']->key,'mode'=>$mode,'operations'=>$assigned],JSON_THROW_ON_ERROR));$pipes=[];$process=proc_open([PHP_BINARY,dirname(__DIR__).'/tests/services-benchmark-child.php',$file],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($process)){throw new RuntimeException('No benchmark process');}fclose($pipes[0]);$children[]=[$process,$pipes];}
        foreach($children as [$process,$pipes]){$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($process));same('',$stderr);array_push($times,...json_decode($stdout,true,32,JSON_THROW_ON_ERROR));}
        $elapsed=(hrtime(true)-$start)/1e9;$after=$db->execute("SHOW GLOBAL STATUS WHERE Variable_name IN ('Innodb_row_lock_time','Innodb_deadlocks')")->fetchAll();$delta=[];foreach($after as $row){foreach($before as $prior){if($row['Variable_name']===$prior['Variable_name']){$delta[$row['Variable_name']]=(int)$row['Value']-(int)$prior['Value'];}}}
        $report['results'][]=['processes'=>$concurrency,'mode'=>$mode==='claim'?'claim including healthy pool selection and reservation':'complete mock worker including independent inspection','samples'=>count($times),'p50_ms'=>$percentile($times,.50),'p95_ms'=>$percentile($times,.95),'throughput_per_second'=>count($times)/$elapsed,'database_status_delta'=>$delta];
    }}}
    finally{\FixtureDirectory::remove($directory);}
    // Scope fixture volume to the already authenticated customer without forging its Identity grants.
    $httpIds=[];for($i=0;$i<50;++$i){$httpIds[]=newHttpService(false);}
    $active=newHttpService();foreach(['client-list'=>'/api/v1/client/services/list','admin-operations'=>'/api/v1/admin/services/detail?customer='.$f['customer'].'&id='.$active] as $view=>$url){$times=[];for($i=0;$i<30;++$i){$start=hrtime(true);same(200,serviceHttp($url)[0]);$times[]=(hrtime(true)-$start)/1e6;}$report['http'][$view]=['samples'=>30,'customer_services'=>(int)$db->execute('SELECT COUNT(*) FROM svc_services WHERE customer_id=?',[$f['customer']])->fetchColumn(),'p50_ms'=>$percentile($times,.5),'p95_ms'=>$percentile($times,.95)];}
    $report['queue_age_seconds']=$db->execute("SELECT MIN(TIMESTAMPDIFF(MICROSECOND,created_at,updated_at)/1000000) AS min_seconds,MAX(TIMESTAMPDIFF(MICROSECOND,created_at,updated_at)/1000000) AS max_seconds,AVG(TIMESTAMPDIFF(MICROSECOND,created_at,updated_at)/1000000) AS mean_seconds FROM svc_operations WHERE order_item_id=? AND status='SUCCEEDED'",[$fixture['item']['id']])->fetch();
    $report['queue_wait_seconds']=$db->execute("SELECT MIN(TIMESTAMPDIFF(MICROSECOND,o.created_at,a.created_at)/1000000) min_seconds,MAX(TIMESTAMPDIFF(MICROSECOND,o.created_at,a.created_at)/1000000) max_seconds,AVG(TIMESTAMPDIFF(MICROSECOND,o.created_at,a.created_at)/1000000) mean_seconds FROM svc_operations o JOIN svc_attempt_events a ON a.operation_id=o.id AND a.kind='STARTED' WHERE o.order_item_id=?",[$fixture['item']['id']])->fetch();
    file_put_contents(dirname(__DIR__).'/docs/evidence/f3/performance.json',json_encode($report,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));
});
